    .addConditionalEdges('review', state => state.action === 'execute' ? 'execute' : END,
      ['execute', END])
    .addConditionalEdges('execute', state => state.outcome.phase === 'result'
      ? nextAfterResult(state) : END, ['read', END])
    .addEdge('read', END);
