    if (workspaceDirectory !== undefined) need(operatorProfile === undefined, 'DATASET_WORKSPACE_PROFILE_UNSUPPORTED');
    metadata.limits = {maxPages,maxTotalAtomic,maxRows,maxPageBytes};
    metadata.expectedSnapshot = expectedSnapshot;
    // Reject non-JSON values before allocating a named application entry.
    jsonBytes(metadata);
    if (config !== undefined) input = await buyer._profile(typeof config === 'string'
      ? await readJson(absolute(config)) : clone(config), operatorProfile);
  }
  if (await exists(dataset.directory)) throw new BuyerError('DATASET_ALREADY_EXISTS_USE_OPEN', {dataset});
  const parent = join(buyer.stateDirectory, 'datasets');
  // Publish a complete entry once. A crash while writing the private stage cannot
  // reserve the stable name or make listDatasets encounter half-written metadata.
  const stage = await mkdtemp(join(parent, '.dataset-stage-'));
  if (input) await writeJson(join(stage, 'config.json'), input, {exclusive:true});
  await writeJson(join(stage, 'dataset.json'), metadata, {exclusive:true});
  await syncDirectory(stage);
  try { await rename(stage, dataset.directory); }
  catch (error) {
    // A concurrently published entry is nonempty and cannot be replaced by rename.
    if (['EEXIST','ENOTEMPTY'].includes(error.code))
      throw new BuyerError('DATASET_ALREADY_EXISTS_USE_OPEN', {dataset, stagingDirectory:stage});
    throw error;
  }
  await syncDirectory(parent);
  if (recoveryOnly) await dataset.initializeRecovery();
  else if (accountingOnly) await dataset.initializeAccounting();
  else await dataset.initialize();
  return dataset;
}

export async function* listDatasets(buyer) {
  await buyer.ready();
  const directory = join(buyer.stateDirectory, 'datasets');
  if (!await exists(directory)) return;
  await privateDirectory(directory, {create:false});
  for (const entry of await readdir(directory, {withFileTypes:true})) {
    if (!entry.isDirectory() || !/^[a-f0-9]{64}$/.test(entry.name)) continue;
    const metadata = await readJson(join(directory, entry.name, 'dataset.json'));
    need(metadata.schema === SCHEMA && digest(intent(metadata.id)) === entry.name,
      'DATASET_APPLICATION_STATE_INVALID');
    yield new Dataset(buyer, metadata.id);
  }
}

/** A file from an original, verified SF100 export. No native purchase summary is fabricated. */
export class DatasetFile extends VerifiedFile {
  constructor(metadata, directory) {
    super();
    this.metadata = freeze(clone(metadata));
    this.directory = absolute(directory);
  }
  _metadata() {
    const saved = this.metadata;
    need(object(saved) && OUTPUTS.has(saved.name) && saved.path === join(this.directory, saved.name) &&
      Number.isSafeInteger(saved.bytes) && saved.bytes >= 0 && saved.bytes <= MAX_OUTPUT &&
      typeof saved.sha256 === 'string' && /^[a-f0-9]{64}$/.test(saved.sha256),
    'DATASET_OUTPUT_METADATA_INVALID');
    return saved;
  }
}

export class DatasetDelivery {
  constructor(report, manifest) {
    this.report = freeze(clone(report));
    this.manifest = freeze(clone(manifest));
  }
  static async open(report) {
    need(report?.schema === 'stellar-forge.sf88.dataset-delivery.v1' &&
      report.nativeStatus?.finalized === true && object(report.outputs), 'DATASET_NATIVE_DELIVERY_INVALID');
    const file = new DatasetFile({name:'manifest.json', ...report.outputs['manifest.json']}, report.directory);
    const manifest = await file.json({limit:4 * 1024 * 1024});
    need(manifest?.schema === 'stellar-forge.buyer-delivery-manifest.v1' &&
      manifest.dataset?.snapshot === report.nativeStatus.snapshot &&
      manifest.dataset.rows === report.nativeStatus.rows && Array.isArray(manifest.dataset.projectedFields) &&
      object(manifest.outputs), 'DATASET_NATIVE_MANIFEST_INVALID');
    const semantics = manifest.semantics;
    need((semantics !== undefined) === (report.semantics !== undefined),
      'DATASET_SEMANTIC_OUTPUT_METADATA_INVALID');
    if (semantics !== undefined) need(object(semantics) && semantics.file === 'semantics.json' &&
      semantics.scope === 'PUBLISHED_DATASET' && semantics.typedRowsFile === 'dataset.jsonl' &&
      ['schema','sha256','definitionSha256','captureManifestSha256'].every(key =>
        semantics[key] === report.semantics[key] && semantics[key] === report.nativeStatus.semantics?.[key]) &&
      JSON.stringify(semantics.selectedFields) === JSON.stringify(manifest.dataset.projectedFields),
      'DATASET_SEMANTIC_OUTPUT_METADATA_INVALID');
    for (const name of ['dataset.jsonl','dataset.csv','review.html',
      ...(semantics !== undefined ? ['semantics.json'] : [])])
      need(manifest.outputs[name]?.sha256 === report.outputs[name]?.sha256 &&
        manifest.outputs[name]?.bytes === report.outputs[name]?.bytes, 'DATASET_OUTPUT_METADATA_INVALID');
    return new DatasetDelivery(report, manifest);
  }
  file(name) {
    need(OUTPUTS.has(name), 'DATASET_OUTPUT_NAME_INVALID');
    return new DatasetFile({name, ...this.report.outputs[name]}, this.report.directory);
  }
  /** The retained published dictionary; selectedFields remain in the delivery manifest. */
  async readSemantics({limit = 2097152, signal} = {}) {
    if (this.manifest.semantics === undefined) return null;
    const value = await this.file('semantics.json').json({limit, signal});
    const binding = this.manifest.semantics;
    need(value?.schema === binding.schema && value.sha256 === binding.sha256 &&
      value.definitionSha256 === binding.definitionSha256 &&
      value.source?.captureManifestSha256 === binding.captureManifestSha256,
      'DATASET_SEMANTIC_DICTIONARY_CHANGED');
    return value;
  }
  _row(text) {
    let value;
    try { value = JSON.parse(text); } catch { throw new BuyerError('DATASET_ROW_JSON_INVALID'); }
    const fields = this.manifest.dataset.projectedFields;
    need(object(value) && Object.keys(value).length === fields.length && fields.every(field =>
      Object.hasOwn(value, field) && (value[field] === null || ['string','number','boolean'].includes(typeof value[field]))),
    'DATASET_ROW_SHAPE_INVALID');
    return value;
  }
  /** Values retain the original SF100 JSON scalar types; no numeric/date coercion. */
  async *rows({signal, maxRowCharacters = 16777216} = {}) {
    need(Number.isSafeInteger(maxRowCharacters) && maxRowCharacters > 0 && maxRowCharacters <= MAX_OUTPUT,
      'DATASET_ROW_LIMIT_INVALID');
    const decoder = new TextDecoder('utf-8', {fatal:true});
    let pending = '', count = 0;
    for await (const chunk of this.file('dataset.jsonl').chunks({signal})) {
      pending += decoder.decode(chunk, {stream:true});
      let newline;
      while ((newline = pending.indexOf('\n')) >= 0) {
        need(newline <= maxRowCharacters, 'DATASET_ROW_LIMIT');
        const text = pending.slice(0, newline); pending = pending.slice(newline + 1);
        need(text.length > 0, 'DATASET_EMPTY_ROW');
        need(++count <= this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
        yield this._row(text);
      }
      need(pending.length <= maxRowCharacters, 'DATASET_ROW_LIMIT');
    }
    pending += decoder.decode();
    if (pending) { count++; yield this._row(pending); }
    need(count === this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
  }
  /** Returns only after the entire output has passed its saved size/hash check. */
  async readRows({limit = 8388608, maxRows = 100000, signal} = {}) {
    need(Number.isSafeInteger(maxRows) && maxRows >= 0 && this.manifest.dataset.rows <= maxRows,
      'DATASET_ROW_LIMIT_EXCEEDED_USE_ROWS');
    const bytes = await this.file('dataset.jsonl').bytes({limit, signal});
    const text = new TextDecoder('utf-8', {fatal:true}).decode(bytes);
    const lines = text.length ? text.replace(/\n$/, '').split('\n') : [];
    need(lines.length === this.manifest.dataset.rows, 'DATASET_ROW_COUNT_CHANGED');
    return lines.map(line => this._row(line));
  }
}

#!/usr/bin/env node
// One explicit original acquisition command; no automatic follow-up payment.
import {readFile} from 'node:fs/promises';
import {AcquisitionWorkspace, AcquisitionError} from '../index.mjs';

const [settingsFile, commandFile, ...extra] = process.argv.slice(2);
if (!settingsFile || !commandFile || extra.length)
  throw new Error('Usage: node acquisitions.mjs /absolute/sdk-settings.json /absolute/command.json');
const settings = JSON.parse(await readFile(settingsFile, 'utf8'));
const {command, parameters:p = {}} = JSON.parse(await readFile(commandFile, 'utf8'));
const workspace = new AcquisitionWorkspace(settings);
const controller = new AbortController();
let interruptedExit = null;
const interrupt = () => {interruptedExit ??= 130; controller.abort();};
const terminate = () => {interruptedExit ??= 143; controller.abort();};
const options = {signal:controller.signal};
const actions = {
  state: () => workspace.state(options),
  attach: () => workspace.attachRun(p.run, options),
  request: () => workspace.request(p.id, options),
  receive: () => workspace.receiveRequest(p.file, {...options, filename:p.filename}),
  'review-request': () => workspace.reviewRequest(p.id, {...p, ...options}),
  'prepare-request': () => workspace.prepareRequest(p.id, {...p, ...options}),
  'paid-file': () => workspace.paidFile(p.id, options),
  'receive-paid-file': () => workspace.receivePaidFile(p.file, {...options, filename:p.filename}),
  'review-paid-file': () => workspace.reviewPaidFile(p.id, {...p, ...options}),
  'prepare-paid-file': () => workspace.preparePaidFile(p.id, {...p, ...options}),
  'retrieve-paid-file': () => workspace.retrievePaidFile(p.id, {...p, ...options}),
  'reset-paid-file': () => workspace.resetPaidFile(p.id, {...p, ...options}),
  'download-paid-file': () => workspace.downloadPaidFile(p.id, p.operationId, p.destination, options),
  'export-paid-file': () => workspace.exportPaidFile(p.id, {...p, ...options}),
  draft: () => workspace.draft(p.id, {...p, ...options}),
  save: () => workspace.save({...p, ...options}),
  initialize: () => workspace.initialize(p.id, {...p, ...options}),
  inspect: () => workspace.inspect(p.id, options),
  execute: () => workspace.execute(p.id, {...p, ...options}),
  recover: () => workspace.recover(p.id, options),
  unlock: () => workspace.unlock(p.id, {...p, ...options}),
  finalize: () => workspace.finalize(p.id, {...p, ...options}),
  'bind-accounting': () => workspace.bindAccounting(p.id, {...p, ...options}),
  preview: () => workspace.preview(p.id, p.operationId, options),
  download: () => workspace.download(p.id, p.operationId, p.destination, options),
  export: () => workspace.export(p.id, {...p, ...options}),
  'export-request': () => workspace.exportRequest(p.id, {...p, ...options}),
  'backup-review': () => workspace.backupReview({...p, ...options}),
  backup: () => workspace.backup({...p, ...options}),
  verify: () => workspace.verify({...p, ...options}),
  restore: () => workspace.restore({...p, ...options}),
};
if (!Object.hasOwn(actions, command)) throw new Error('Choose one command: ' + Object.keys(actions).join(', '));
process.on('SIGINT', interrupt); process.on('SIGTERM', terminate);
try {
  const result = await actions[command]();
  process.stdout.write(JSON.stringify(result, null, 2) + '\n');
} catch (error) {
  if (!(error instanceof AcquisitionError)) throw error;
  process.stdout.write(JSON.stringify({code:error.code, result:error.result}, null, 2) + '\n');
  process.exitCode = interruptedExit ?? 2;
} finally {
  process.off('SIGINT', interrupt); process.off('SIGTERM', terminate);
}

// MIT — A typed customer program; runtime and state identify an existing buyer.
import { Buyer } from '../index.mjs';
import { createSqliteBuyerGraph } from '../agents/sqlite.mjs';
import { createBuyerTools } from '../agents/langchain.mjs';
import type { ResponseArtifact } from '../agents/operation.mjs';

export async function readExistingOperation(options: {
  runtimeDirectory: string; stateDirectory: string; intentId: string;
  checkpointFile: string; threadId: string;
}): Promise<ResponseArtifact | null> {
  const buyer = new Buyer({ runtimeDirectory: options.runtimeDirectory, stateDirectory: options.stateDirectory });
  const operation = buyer.operation(options.intentId);
  const session = await createSqliteBuyerGraph({ operation,
    databasePath: options.checkpointFile, read: { format: 'json' } });
  try {
    const state = await session.graph.invoke({ action: 'recover' }, {
      configurable: { thread_id: options.threadId }, durability: 'sync',
    });
    return state.artifact;
  } finally { session.close(); }
}

export async function readWithLangChain(options: {
  runtimeDirectory: string; stateDirectory: string; intentId: string; toolCallId: string;
}) {
  const buyer = new Buyer({ runtimeDirectory: options.runtimeDirectory, stateDirectory: options.stateDirectory });
  const tools = createBuyerTools({ operation: buyer.operation(options.intentId) });
  const read = tools.find(item => item.name === 'stellar_buyer_read')!;
  return read.invoke({ type: 'tool_call', id: options.toolCallId, name: read.name,
    args: { format: 'json' } });
}

#!/usr/bin/env node
// MIT — Operate an existing buyer intent through real optional frameworks.
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { randomUUID } from 'node:crypto';
import { Buyer } from '../index.mjs';
import { BuyerAgent } from '../agents/operation.mjs';

const usage = `Stellar native buyer: framework operator

  node examples/agent-workflow.mjs graph --runtime ABS --state ABS --intent ID
    --checkpoints ABS --thread ID [--action recover|review|execute]
    [--read-format file|json|text|base64|csv|sse|ndjson] [--pause-after inspect]
  node examples/agent-workflow.mjs resume --runtime ABS --state ABS --intent ID
    --checkpoints ABS --thread ID [--read-format json]
  node examples/agent-workflow.mjs status --runtime ABS --state ABS --intent ID
    --checkpoints ABS --thread ID
  node examples/agent-workflow.mjs tool --runtime ABS --state ABS --intent ID
    --tool review|execute|recover|read [--read-format json]
  node examples/agent-workflow.mjs export --runtime ABS --state ABS --intent ID
    --out ABS

All commands attach to the existing private operation. The framework checkpoint
directory must be private. graph defaults to recovery; execute is explicit.
Use the same checkpoint file and thread to resume a paused or interrupted graph.
`;

function argumentsFor(argv) {
  const [requested = 'help', ...rest] = argv;
  const command = ['--help', '-h'].includes(requested) ? 'help' : requested;
  const allowed = new Set(['runtime', 'state', 'intent', 'checkpoints', 'thread', 'action',
    'read-format', 'pause-after', 'tool', 'out', 'offset', 'limit-records', 'limit-bytes',
    'allow-partial', 'tool-call-id']);
  const flags = {};
  for (let i = 0; i < rest.length; i += 2) {
    const key = rest[i].replace(/^--/, '');
    if (!rest[i].startsWith('--') || !allowed.has(key) || flags[key] !== undefined ||
      rest[i + 1] === undefined) throw new Error('ARGUMENT_INVALID: ' + rest[i]);
    flags[key] = rest[i + 1];
  }
  const required = names => { for (const name of names) if (!flags[name]) throw new Error('ARGUMENT_REQUIRED: --' + name); };
  if (command !== 'help') required(['runtime', 'state', 'intent']);
  if (['graph', 'resume', 'status'].includes(command)) required(['checkpoints', 'thread']);
  if (command === 'export') required(['out']);
  if (command === 'tool') required(['tool']);
  const read = { format: flags['read-format'] ?? 'file' };
  for (const [flag, key] of [['offset', 'offset'], ['limit-records', 'limitRecords'], ['limit-bytes', 'limitBytes']])
    if (flags[flag] !== undefined) read[key] = Number(flags[flag]);
  if (flags['allow-partial'] !== undefined) {
    if (!['true', 'false'].includes(flags['allow-partial'])) throw new Error('BOOLEAN_REQUIRED: --allow-partial');
    read.allowPartial = flags['allow-partial'] === 'true';
  }
  return { command, flags, read };
}

function graphOutput(state) {
  return { binding: state.binding ?? null, action: state.action ?? null, phase: state.phase ?? null,
    outcome: state.outcome ?? null, artifact: state.artifact ?? null,
    reviewAvailable: Boolean(state.nativeReview), readOptions: state.readOptions ?? null };
}

export async function main(argv = process.argv.slice(2)) {
  const { command, flags, read } = argumentsFor(argv);
  if (command === 'help') { process.stdout.write(usage); return; }
  const buyer = new Buyer({ runtimeDirectory: flags.runtime, stateDirectory: flags.state });
  const operation = buyer.operation(flags.intent);
  let output;
  if (['graph', 'resume', 'status'].includes(command)) {
    const { createSqliteBuyerGraph } = await import('../agents/sqlite.mjs');
    const session = await createSqliteBuyerGraph({ operation, databasePath: flags.checkpoints,
      read, interruptAfter: flags['pause-after'] ? flags['pause-after'].split(',') : [] });
    const config = { configurable: { thread_id: flags.thread }, durability: 'sync' };
    try {
      if (command === 'status') {
        const snapshot = await session.graph.getState(config);
        if (snapshot.values.binding) await new BuyerAgent(operation).binding(snapshot.values.binding);
        output = { ...graphOutput(snapshot.values), next: snapshot.next,
          checkpoint: snapshot.config.configurable?.checkpoint_id ?? null };
      } else {
        if (command === 'resume') {
          const saved = await session.graph.getState(config);
          if (!saved.values.binding) throw new Error('CHECKPOINT_NOT_FOUND');
          await new BuyerAgent(operation).binding(saved.values.binding);
        }
        const state = await session.graph.invoke(command === 'resume' ? null :
          { action: flags.action ?? 'recover' }, config);
        const snapshot = await session.graph.getState(config);
        output = { ...graphOutput(state), next: snapshot.next,
          checkpoint: snapshot.config.configurable?.checkpoint_id ?? null };
      }
    } finally { session.close(); }
  } else if (command === 'tool') {
    const { createBuyerTools } = await import('../agents/langchain.mjs');
    const tool = createBuyerTools({ operation }).find(item => item.name === 'stellar_buyer_' + flags.tool);
    if (!tool) throw new Error('TOOL_INVALID');
    const response = await tool.invoke({ type: 'tool_call', id: flags['tool-call-id'] ?? randomUUID(),
      name: tool.name, args: flags.tool === 'read' ? read : {} });
    output = { name: response.name, toolCallId: response.tool_call_id, content: response.content,
      artifact: response.artifact };
  } else if (command === 'export') {
    output = await new BuyerAgent(operation).saveAs(flags.out);
  } else throw new Error('COMMAND_INVALID');
  process.stdout.write(JSON.stringify(output, null, 2) + '\n');
  return output;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => {
    process.stderr.write(JSON.stringify({ error: error.code ?? error.message, name: error.name }) + '\n');
    process.exitCode = 1;
  });

