const allowed = new Set(['runtime', 'state', 'profile', 'client', 'operation', 'inputs', 'intent', 'max-atomic', 'accept', 'output',
  'dataset','config','workspace','session','max-pages','max-total-atomic','max-rows','max-page-bytes','snapshot',
