import { captureChildProcessIdentity } from './process-identity.mjs';


async function allocateOutput(fileHandle, path, kind, bytes, signal, reserveFile) {
  if (!reserveFile) return;
  need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
  const fd = fileHandle.fd;
  const before = await fileHandle.stat({ bigint: true });
  need(before.isFile() && before.size === 0n, 'NATIVE_OUTPUT_ALLOCATION_TARGET_INVALID');
  // The caller owns this live descriptor. Allocators reserve its backing space
  // with KEEP_SIZE and must settle before returning or relinquishing this handle.
  await reserveFile(Object.freeze({ fileHandle, path, kind, bytes, signal }));
  const after = await fileHandle.stat({ bigint: true });
  const named = await lstat(path, { bigint: true });
  need(fileHandle.fd === fd && after.isFile() && named.isFile() && !named.isSymbolicLink() &&
    before.dev === after.dev && before.ino === after.ino && before.size === after.size &&
    before.mode === after.mode && before.uid === after.uid && before.gid === after.gid &&
    before.nlink === after.nlink && named.dev === after.dev && named.ino === after.ino &&
    named.size === after.size && named.mode === after.mode && named.uid === after.uid &&
    named.gid === after.gid, 'NATIVE_OUTPUT_ALLOCATION_TARGET_CHANGED');
  need(typeof after.blocks === 'bigint' && after.blocks * 512n >= BigInt(bytes),
    'NATIVE_OUTPUT_ALLOCATION_INCOMPLETE');
  await fileHandle.sync();
  need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
}

async function closeOutput(fileHandle, { reserved = false, reset = false, limit } = {}) {
  if (!fileHandle) return;
  let failure;
  if (reserved) {
    try {
      // KEEP_SIZE may allocate beyond EOF. Trim to the actual logical output,
      // including zero on a failed pre-spawn allocation; never publish padding.
      const length = reset ? 0 : Math.min((await fileHandle.stat()).size, limit);
      await fileHandle.truncate(length);
      await fileHandle.sync();
    } catch (error) { failure = error; }
  }
  try { await fileHandle.close(); } catch (error) { failure ??= error; }
  if (failure) throw failure;
}

export const resultRecordLimit = runtime => Math.min(2147483647, 2 * runtime.outputLimit + 16384);
export const attemptRecordLimit = 65536;

export class NativeRuntime {
  constructor({ runtimeDirectory, node = process.execPath, environment = process.env,
    timeoutMs = 360000, cleanupGraceMs = 15000, outputLimit = 1048576, reserveFile, nativeFileReservation, nativeRuntimeSource }) {
    this.directory = absolute(runtimeDirectory);
    this.cli = join(this.directory, 'cli.mjs');
    this.node = absolute(node);
    this.environment = { ...environment };
    for (const [name, value] of Object.entries({ timeoutMs, cleanupGraceMs, outputLimit }))
      need(Number.isSafeInteger(value) && value > 0 && value <= 2147483647, 'RUNTIME_LIMIT_INVALID');
    need(reserveFile === undefined || typeof reserveFile === 'function', 'NATIVE_RESERVE_FILE_CALLBACK_INVALID');
    Object.assign(this, { timeoutMs, cleanupGraceMs, outputLimit, reserveFile,
      nativeFileReservation: normalizeNativeFileReservation(nativeFileReservation),
      nativeRuntimeSource: nativeRuntimeSource === undefined ? undefined :
        Object.freeze(parseJson(jsonBytes(nativeRuntimeSource))) });
  }

  async fileReservation() {
    if (this.reserveFile) return this.reserveFile;
    const inherited = currentFileReservation()?.reserveFile;
    if (inherited) return inherited;
    return this.nativeFileReservation ? createNativeFileReservation(this.nativeFileReservation) : null;
  }

  async run(args, options = {}) {
    const launch = { invoked: false, settled: false, nativeProcessStarted: false, command: null, commandSha256: null };
    try {
      const result = await this._run(args, options, launch);
      return { ...result, nativeProcessStarted: launch.nativeProcessStarted,
        command: launch.command, commandSha256: launch.commandSha256 };
    } catch (error) {
      if (!launch.invoked || launch.settled && !launch.nativeProcessStarted)
        throw new BuyerError(safeCode(error?.code, 'NATIVE_PRESPAWN_FAILED'), {
          nativeProcessStarted: false, command: launch.command, commandSha256: launch.commandSha256,
          ...(error?.outputCleanupFailed === true ? { outputCleanupFailed: true } : {}),
        });
      throw error;
    }
  }

  async _run(args, { directory, signal, started, beforeSpawn, entryFile = this.cli, resultFile,
    resultLimit = this.outputLimit } = {}, launch) {
    need(Array.isArray(args) && args.every(value => typeof value === 'string' && !value.includes('\0')), 'NATIVE_ARGUMENTS_INVALID');
    need(signal === undefined || signal instanceof AbortSignal, 'INVALID_ABORT_SIGNAL');
    need(Number.isSafeInteger(resultLimit) && resultLimit > 0 && resultLimit <= 268435456, 'NATIVE_RESULT_LIMIT_INVALID');
    entryFile = absolute(entryFile);
    need(beforeSpawn === undefined || typeof beforeSpawn === 'function', 'NATIVE_BEFORE_SPAWN_INVALID');
    launch.command = [this.node, entryFile, ...args];
    launch.commandSha256 = digest(jsonBytes(launch.command));
    need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
    if (this.nativeRuntimeSource !== undefined) {
      const { verifySuccessorRuntimeSource } = await import('./runtime-source.mjs');
      const binding = await verifySuccessorRuntimeSource(this.nativeRuntimeSource, { signal });
      need(binding.directory === this.directory, 'NATIVE_RUNTIME_SOURCE_DIRECTORY_MISMATCH');
    }
    need((await lstat(entryFile)).isFile(), 'NATIVE_CLI_REQUIRED');
    // ESM resolves parent directory links before evaluating a main-entry guard.
    // Pass that same real filename in argv while keeping the regular-file check.
    entryFile = await realpath(entryFile);
    launch.command = [this.node, entryFile, ...args];
    launch.commandSha256 = digest(jsonBytes(launch.command));
    directory = await privateDirectory(directory, { create: false });
    resultFile = resultFile === undefined ? join(directory, 'stdout.json') : absolute(resultFile);
    need(dirname(resultFile) === directory, 'NATIVE_RESULT_PATH_INVALID');
    // Native writes directly to private descriptors. A parent crash does not
    // discard a later complete native summary, which recover() can read.
    const reserveFile = await this.fileReservation();
    need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
    let nativeArgs = [entryFile, ...args];
    if (this.nativeFileReservation) {
      const bootstrap = await realpath(join(this.directory, 'node', 'reserved-entry.mjs'));
      need((await lstat(bootstrap)).isFile(), 'NATIVE_RESERVED_ENTRY_REQUIRED');
      const requestPath = join(directory, 'native-reserved-request.json');
      const request = jsonBytes({
        schema: 'stellar-forge.sf88.reserved-entry.v1', entryFile,
        entrySha256: digest(await readBytes(entryFile, 16777216)),
        args: [...args], nativeFileReservation: this.nativeFileReservation,
        ...(this.nativeRuntimeSource === undefined ? {} : { nativeRuntimeSource: this.nativeRuntimeSource }),
      });
      need(request.length <= 2097152, 'NATIVE_RESERVED_REQUEST_LIMIT');
      await withFileReservation({ reserveFile, signal },
        () => writeBytes(requestPath, request, { exclusive: true }));
      nativeArgs = [bootstrap, requestPath, digest(request)];
      launch.command = [this.node, ...nativeArgs];
      launch.commandSha256 = digest(jsonBytes(launch.command));
    }
    const stdoutPath = join(directory, 'stdout.json');
    const stderrPath = join(directory, 'stderr.log');
    const stdout = await open(stdoutPath, 'wx', 0o600);
    let stderr;
    try {
      stderr = await open(stderrPath, 'wx', 0o600);
      await allocateOutput(stdout, stdoutPath, 'native-stdout', this.outputLimit, signal, reserveFile);
      await allocateOutput(stderr, stderrPath, 'native-stderr', this.outputLimit, signal, reserveFile);
      need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
    } catch (error) {
      // A second-allocation failure must also release the first held extent.
      // Settle both cleanups so one failing descriptor cannot leak its peer.
      const cleanup = await Promise.allSettled([stdout, stderr].filter(Boolean).map(fileHandle =>
        closeOutput(fileHandle, { reserved: Boolean(reserveFile), reset: true, limit: this.outputLimit })));
      if (cleanup.some(item => item.status === 'rejected'))
        throw new BuyerError(safeCode(error?.code, 'NATIVE_OUTPUT_ALLOCATION_FAILED'), { outputCleanupFailed: true });
      throw error;
    }
    let child, exitCode = null, exitSignal = null, localError = null;
    let timeout, grace, monitor, closed = false, startRecording = Promise.resolve();
    const stop = code => {
      localError ??= code;
      if (!child || closed || child.exitCode !== null || child.signalCode !== null) return;
      if (!grace) {
        child.kill('SIGTERM');
        grace = setTimeout(() => {
          if (!closed && child.exitCode === null && child.signalCode === null) {
            localError = 'NATIVE_CLEANUP_DEADLINE_EXCEEDED';
            child.kill('SIGKILL');
          }
        }, this.cleanupGraceMs);
        grace.unref();
      }
    };
    const abort = () => stop('OPERATION_ABORTED');
    try {
      if (beforeSpawn) await beforeSpawn({ command: [...launch.command], commandSha256: launch.commandSha256 });
      need(!signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
      await new Promise(resolveClose => {
        try {
          launch.invoked = true;
          child = spawn(this.node, nativeArgs, {
            cwd: this.directory, env: this.environment, shell: false,
            stdio: ['inherit', stdout.fd, stderr.fd], windowsHide: true,
          });
        } catch { localError = 'NATIVE_START_FAILED'; launch.settled = true; resolveClose(); return; }
        child.once('error', () => { localError ??= 'NATIVE_PROCESS_ERROR'; });
        child.once('spawn', () => {
          launch.nativeProcessStarted = true;
          startRecording = Promise.resolve().then(async () => {
            if (started) await started(child.pid, await captureChildProcessIdentity(child.pid));
          }).catch(() => stop('ATTEMPT_STATE_WRITE_FAILED'));
        });
        child.once('close', (code, nativeSignal) => {
          closed = true; launch.settled = true; exitCode = code; exitSignal = nativeSignal; resolveClose();
        });
        timeout = setTimeout(() => stop('NATIVE_TIMEOUT'), this.timeoutMs);
        timeout.unref();
        // No raw stdout/stderr enters application callbacks. Enforce a private
        // log budget; the native command's own limits remain authoritative.
        let checking = false;
        monitor = setInterval(async () => {
          if (checking || closed) return;
          checking = true;
          try {
            const sizes = await Promise.all([stdout.stat(), stderr.stat()]);
            if (sizes.some(stat => stat.size > this.outputLimit)) stop('NATIVE_OUTPUT_LIMIT');
          } catch { if (!closed) stop('NATIVE_LOG_IO_FAILED'); }
          finally { checking = false; }
        }, 100);
        monitor.unref();
        signal?.addEventListener('abort', abort, { once: true });
        if (signal?.aborted) abort();
      });
      await startRecording;
      for (const handle of [stdout, stderr]) {
        if ((await handle.stat()).size > this.outputLimit) {
          localError = 'NATIVE_OUTPUT_LIMIT';
          await handle.truncate(this.outputLimit);
        }
      }
      await Promise.all([stdout.sync(), stderr.sync()]);
    } finally {
      clearTimeout(timeout); clearTimeout(grace); clearInterval(monitor);
      signal?.removeEventListener('abort', abort);
      const outputCleanup = await Promise.allSettled([stdout, stderr].map(fileHandle =>
        closeOutput(fileHandle, { reserved: Boolean(reserveFile), limit: this.outputLimit })));
      const failedCleanup = outputCleanup.find(result => result.status === 'rejected');
      if (failedCleanup) {
        if (!reserveFile) throw failedCleanup.reason;
        // Complete native stdout remains recoverable even if releasing unused
        // backing space fails; do not replace its result with a cleanup exception.
        localError ??= 'NATIVE_OUTPUT_RESERVATION_RELEASE_FAILED';
      }
    }
    let output = null, nativeError = null, unavailable = false;
    try { const value = parseJson(await readBytes(resultFile, resultLimit)); if (object(value)) output = value; }
    catch { unavailable = true; }
    try {
      const raw = await readBytes(join(directory, 'stderr.log'), this.outputLimit);
      const line = raw.toString('utf8').trim().split('\n').at(-1);
      const parsed = JSON.parse(line);
      nativeError = safeCode(parsed?.error, null);
    } catch { /* Raw stderr is private, never an exception message. */ }
    return { exitCode, exitSignal, errorCode: localError ?? nativeError ?? (unavailable ? 'NATIVE_RESULT_UNAVAILABLE' : null), output };
  }

  async checked(args, { stateDirectory, mode, signal, entryFile } = {}) {
    const directory = await mkdtemp(join(stateDirectory, '.native-'));
    try {
      const run = await this.run(args, { directory, signal, entryFile });
      if (run.exitCode !== 0 || run.errorCode || !run.output || run.output.mode !== mode)
        throw new BuyerError(run.errorCode ?? 'NATIVE_COMMAND_FAILED', { exitCode: run.exitCode });
      return run.output;
    } finally { await rm(directory, { recursive: true, force: true }); }
  }
}

/** A definite closed pre-spawn failure qualifies; an unknown interruption does not. */
export function unstartedAttempt(attempt, observation) {
  if (observation?.nativeProcessStarted !== false || !Array.isArray(observation.command) ||
      observation.command.some(value => typeof value !== 'string') ||
      digest(jsonBytes(observation.command)) !== observation.commandSha256) return null;
  const observedAt = now(), startedAt = attempt.startedAt ?? attempt.createdAt;
  return { ...attempt, state: 'NOT_DISPATCHED', startedAt, endedAt: observedAt,
    nativeStart: {
      schema: 'stellar-forge.node-native-start-receipt.v1',
      nativeProcessStarted: false, phase: 'BEFORE_SPAWN',
      attemptStartedAt: startedAt, observedAt,
      errorCode: safeCode(observation.errorCode ?? observation.code, 'NATIVE_PRESPAWN_FAILED'),
      command: [...observation.command], commandSha256: observation.commandSha256,
    },
  };
}

// MIT. Customer continuation of original session accounting, never another ledger.
import { mkdtemp, readdir, open, link, unlink } from 'node:fs/promises';
import { basename, dirname, join } from 'node:path';
import { createHash, randomUUID } from 'node:crypto';
import { absolute, privateDirectory, digest, now, object, need, BuyerError,
  jsonBytes, readJson, writeJson, exists, syncDirectory, safeCode } from './store.mjs';

const SCHEMA = 'stellar-forge.node-session-accounting-command.v1';
const NATIVE = 'stellar-forge.sf88.session-accounting.v1';
const COMMAND = /^(accounting|finalize)-[A-Za-z0-9]{6}$/;
const freeze = value => {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
};
const clone = value => JSON.parse(jsonBytes(value));
const same = (left, right) => jsonBytes(left).equals(jsonBytes(right));
const unknownProcess = () => ({exitCode:null, exitSignal:null, errorCode:'PROCESS_EXIT_NOT_RECORDED'});

export function accountingOptions({workspaceDirectory, offset = 0, limit = 100, signal,
  outboxDirectory, merchantRoute} = {}, finalize = false) {
  need(Number.isSafeInteger(offset) && offset >= 0 && Number.isSafeInteger(limit) &&
    limit >= 1 && limit <= 250, 'SESSION_ACCOUNTING_RANGE_INVALID');
  need(signal === undefined || signal instanceof AbortSignal, 'INVALID_ABORT_SIGNAL');
  need(finalize || outboxDirectory === undefined && merchantRoute === undefined,
    'ACCOUNTING_VIEW_HAS_NO_OUTBOX');
  need((outboxDirectory !== undefined) === (merchantRoute !== undefined),
    'OUTBOX_AND_ORIGINAL_MERCHANT_ROUTE_REQUIRED_TOGETHER');
  if (merchantRoute !== undefined) need(typeof merchantRoute === 'string' &&
    /^[A-Za-z0-9._:-]{1,160}$/.test(merchantRoute), 'ACCOUNTING_MERCHANT_ROUTE_INVALID');
  return {offset, limit, signal,
    workspaceDirectory:workspaceDirectory === undefined ? null : absolute(workspaceDirectory),
    outboxDirectory:outboxDirectory === undefined ? null : absolute(outboxDirectory),
    merchantRoute:merchantRoute ?? null};
}

function nativeRecord(context, output) {
  const native = context.identity.kind === 'object' ? output?.report : output?.result;
  if (context.identity.kind === 'object') need(output?.mode === 'ORIGINAL_PYTHON_OBJECT' &&
    output.action === context.action, 'SESSION_ACCOUNTING_NATIVE_RESULT_INVALID');
  else need(output?.schema === 'stellar-forge.node-dataset-command.v1' &&
    output.id === context.identity.id && output.command === context.action,
  'SESSION_ACCOUNTING_NATIVE_RESULT_INVALID');
  const identity = context.identity, range = native?.range, request = context.request;
  need(native?.schema === NATIVE && native.kind === identity.kind &&
    native.directory === identity.sessionDirectory && native.sessionId === identity.sessionId &&
    native.configurationSha256 === identity.configurationSha256 &&
    native.mode === (context.action === 'finalize' ? 'FINALIZE' : 'VIEW') &&
    (request.workspaceDirectory === null || native.workspace === request.workspaceDirectory) &&
    (identity.workspace === null || native.workspace === identity.workspace) &&
    object(range) && range.offset === request.offset && range.limit === request.limit &&
    Number.isSafeInteger(range.total) && range.total >= range.offset &&
    Array.isArray(native.entries) && native.entries.length <= range.limit &&
    native.entries.length <= range.total - range.offset && typeof native.interrupted === 'boolean',
  'SESSION_ACCOUNTING_BINDING_CHANGED');
  const next = range.offset + native.entries.length;
  need(range.nextOffset === (next < range.total ? next : null) &&
    native.entries.every((entry, index) => object(entry) &&
      entry.index === range.offset + index + (identity.kind === 'dataset' ? 1 : 0) &&
      typeof entry.outcome === 'string'), 'SESSION_ACCOUNTING_RANGE_CHANGED');
  return {native:clone(native), record:clone(output)};
}

function commandResult(context, output, process, extra = {}) {
  return {...nativeRecord(context, output), process:clone(process), commandId:context.commandId,
    commandDirectory:context.commandDirectory, startedAt:context.startedAt, ...extra};
}

/** Retain the exact native output even if the calling process dies before its reply. */
export async function runAccounting(target, identity, action, options, {outputFile, invoke,
  resultLimit = target.buyer.datasetReportLimit}) {
  need(['accounting','finalize'].includes(action), 'SESSION_ACCOUNTING_ACTION_INVALID');
  need(!options.signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
  const parent = await privateDirectory(join(target.directory, 'commands'));
  const directory = await mkdtemp(join(parent, action + '-'));
  const {signal, ...request} = options;
  const context = {schema:SCHEMA, identity, action, request, startedAt:now(),
    commandId:basename(directory), commandDirectory:directory, outputFile,
    resultLimit};
  await writeJson(join(directory, 'context.json'), context, {exclusive:true});
  // Persist the named command entry before its original financial action starts.
  await syncDirectory(parent);
  let run;
  try { run = await invoke({directory, signal, resultFile:join(directory, outputFile)}); }
  catch (error) {
    run = {output:null, exitCode:null, exitSignal:null,
      errorCode:safeCode(error.code, 'ACCOUNTING_PROCESS_RESULT_UNAVAILABLE')};
  }
  const process = {exitCode:run.exitCode, exitSignal:run.exitSignal, errorCode:run.errorCode};
  let result = null;
  try { if (run.output) result = commandResult(context, run.output, process); }
  catch (error) { process.errorCode = error.code; }
  let viewStatus = 'SAVED';
  try {
    await writeJson(join(directory, 'completion.json'), {schema:SCHEMA,
      contextSha256:digest(jsonBytes(context)), completedAt:now(), process,
      output:result ? run.output : null}, {exclusive:true});
    if (result) await writeJson(join(target.directory, 'last-accounting.json'),
      {completedAt:now(), ...result});
  } catch { viewStatus = 'SAVE_FAILED'; }
  if (!result) throw new BuyerError(process.errorCode ?? 'SESSION_ACCOUNTING_NATIVE_RESULT_UNAVAILABLE',
    {commandId:context.commandId, commandDirectory:directory, exitCode:process.exitCode,
      ...(identity.kind === 'object' ? {acquisition:target} : {dataset:target})});
  const returned = freeze({...result, viewStatus});
  target.lastAccounting = returned;
  return returned;
}

async function readCommand(target, identity, name) {
  need(COMMAND.test(name), 'SESSION_ACCOUNTING_COMMAND_ID_INVALID');
  const directory = join(target.directory, 'commands', name);
  await privateDirectory(directory, {create:false});
  const context = await readJson(join(directory, 'context.json'));
  need(context.schema === SCHEMA && context.commandId === name &&
    context.commandDirectory === directory && same(context.identity, identity) &&
    ['accounting','finalize'].includes(context.action) && name.startsWith(context.action + '-') &&
    ['stdout.json','native.json'].includes(context.outputFile) &&
    Number.isSafeInteger(context.resultLimit) && context.resultLimit > 0 &&
    context.resultLimit <= 268435456 && Number.isFinite(Date.parse(context.startedAt)),
  'SESSION_ACCOUNTING_COMMAND_BINDING_CHANGED');
  const request = accountingOptions({...context.request,
    workspaceDirectory:context.request.workspaceDirectory ?? undefined,
    outboxDirectory:context.request.outboxDirectory ?? undefined,
    merchantRoute:context.request.merchantRoute ?? undefined}, context.action === 'finalize');
  delete request.signal;
  need(same(context.request, request), 'SESSION_ACCOUNTING_COMMAND_BINDING_CHANGED');
  let process = unknownProcess(), result = null, status = 'NO_COMPLETE_OUTPUT';
  const completionPath = join(directory, 'completion.json');
  if (await exists(completionPath)) {
    const completed = await readJson(completionPath, context.resultLimit + 65536);
    need(completed.schema === SCHEMA && completed.contextSha256 === digest(jsonBytes(context)) &&
      object(completed.process), 'SESSION_ACCOUNTING_COMPLETION_CHANGED');
    process = completed.process;
    if (completed.output) {
      result = commandResult(context, completed.output, process, {viewStatus:'SAVED', recovered:false});
      status = 'RECORDED';
    }
  }
  if (!result) {
    try {
      const output = await readJson(join(directory, context.outputFile), context.resultLimit);
      result = commandResult(context, output, process, {viewStatus:'RECOVERED_NATIVE_OUTPUT', recovered:true});
      status = 'OUTPUT_RECOVERED';
    } catch (error) {
      if (!['ENOENT','JSON_INVALID','JSON_OBJECT_REQUIRED','FILE_SIZE_OR_TYPE_INVALID'].includes(error.code)) throw error;
    }
  }
  return {commandId:name, commandDirectory:directory, action:context.action,
    startedAt:context.startedAt, status, process, result};
}

/** Local read only: no process, provider request, finalizer or buyer is started. */
export async function recoverAccounting(target, identity, {commandId} = {}) {
  const parent = join(target.directory, 'commands');
  if (!await exists(parent)) return null;
  await privateDirectory(parent, {create:false});
  if (commandId !== undefined) {
    const selected = await readCommand(target, identity, commandId);
    return freeze({...selected, lastComplete:selected.result});
  }
  const candidates = [];
  for (const item of await readdir(parent, {withFileTypes:true})) {
    if (!item.isDirectory() || !COMMAND.test(item.name) ||
      !await exists(join(parent, item.name, 'context.json'))) continue;
    const context = await readJson(join(parent, item.name, 'context.json'));
    need(typeof context.startedAt === 'string', 'SESSION_ACCOUNTING_COMMAND_BINDING_CHANGED');
    candidates.push({name:item.name, startedAt:context.startedAt});
  }
  candidates.sort((a,b) => b.startedAt.localeCompare(a.startedAt) || b.name.localeCompare(a.name));
  if (!candidates.length) return null;
  const latest = await readCommand(target, identity, candidates[0].name);
  let lastComplete = latest.result;
  // Read only as far back as the latest complete original response, not every
  // historical report into memory when an application reopens its account.
  for (let index = 1; !lastComplete && index < candidates.length; index++)
    lastComplete = (await readCommand(target, identity, candidates[index].name)).result;
  // A later interrupted command cannot erase the earlier original response.
  return freeze({...latest, lastComplete});
}

/** Yield each unchanged native range; a caller break or cancellation starts no next range. */
export async function* accountingPages(target, options = {}, finalize = false) {
  const selected = accountingOptions(options, finalize);
  const identity = await target._accountingIdentity();
  let offset = selected.offset, total = null;
  while (true) {
    need(!selected.signal?.aborted, 'OPERATION_ABORTED_BEFORE_START');
    need(same(identity, await target._accountingIdentity()), 'SESSION_ACCOUNTING_BINDING_CHANGED');
    const input = {offset, limit:selected.limit, signal:selected.signal,
      ...(selected.workspaceDirectory === null ? {} : {workspaceDirectory:selected.workspaceDirectory}),
      ...(selected.outboxDirectory === null ? {} : {outboxDirectory:selected.outboxDirectory, merchantRoute:selected.merchantRoute})};
    const result = await target[finalize ? 'finalize' : 'accounting'](input);
    need(result.native.sessionId === identity.sessionId &&
      result.native.configurationSha256 === identity.configurationSha256 &&
      result.native.directory === identity.sessionDirectory, 'SESSION_ACCOUNTING_BINDING_CHANGED');
    total ??= result.native.range.total;
    yield result;
    if (result.native.range.total !== total) throw new BuyerError('ACCOUNTING_SESSION_LENGTH_CHANGED',
      {lastResult:result, nextOffset:result.native.range.nextOffset});
    if (result.native.interrupted || result.process.errorCode || ![0,2].includes(result.process.exitCode) ||
      selected.signal?.aborted || result.native.range.nextOffset === null) return;
    need(result.native.range.nextOffset > offset, 'SESSION_ACCOUNTING_RANGE_DID_NOT_ADVANCE');
    offset = result.native.range.nextOffset;
  }
}

/** Stream complete original VIEW ranges to a new private JSONL file. */
export async function exportAccounting(target, destination, options = {}) {
