/** Validate a retained purchase through the installed original request reader. */
export async function verifyPartitionPurchase(value, { runtimeDirectory } = {}) {
  need(object(value) && value.schema === PARTITION_PURCHASE_SCHEMA && same(value.source, UNSTRUCTURED_SOURCE) &&
    typeof value.workspaceId === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(value.workspaceId) &&
    typeof value.intentId === 'string' && value.intentId.length > 0 && value.intentId.length <= 512 &&
    hex(value.configurationSha256) && object(value.selection) && object(value.native),
  'UNSTRUCTURED_SAVED_PURCHASE_REQUIRED');
  const chosen = routeSelection({ ...value.selection, expect: { paymentFlow: value.selection.paymentFlow } });
  need(chosen.profileId === value.selection.profileId &&
    value.native.httpStatus === 200 && value.native.responseStatus === 'SAVED' &&
    typeof value.native.status === 'string', 'UNSTRUCTURED_SAVED_SELECTION_INVALID');
  const raw = decodePartitionBytes(value.request, PARTITION_LIMITS.requestBytes);
  const reviewed = await reviewedDocument(runtimeDirectory, raw, value.selection.contentType);
  need(same(value.selection.parameters, reviewed.parameters) &&
    value.selection.parametersSha256 === reviewed.parametersSha256 &&
    same(value.document, reviewed.document), 'UNSTRUCTURED_SAVED_DOCUMENT_PROFILE_CHANGED');
  const response = decodePartitionBytes(value.response, PARTITION_LIMITS.responseBytes);
  const elements = parsePartitionElements(parseJson(response));
  need(same(value.summary, partitionElementSummary(elements)), 'UNSTRUCTURED_SAVED_SUMMARY_CHANGED');
  return { purchase: value, elements, document: decodePartitionBytes(value.document, PARTITION_LIMITS.documentBytes) };
}
export function partitionPurchaseBinding(purchase) {
  return {
    schema: PARTITION_PURCHASE_SCHEMA, workspaceId: purchase.workspaceId, intentId: purchase.intentId,
    configurationSha256: purchase.configurationSha256,
    method: purchase.selection.method, url: purchase.selection.url,
    profileId: purchase.selection.profileId, paymentFlow: purchase.selection.paymentFlow,
    parametersSha256: purchase.selection.parametersSha256,
    document: {
      filename: purchase.document.filename, contentType: purchase.document.contentType,
      bytes: purchase.document.bytes, sha256: purchase.document.sha256,
    },
    requestSha256: purchase.request.sha256, requestBytes: purchase.request.bytes,
    responseSha256: purchase.response.sha256, responseBytes: purchase.response.bytes,
    native: structuredClone(purchase.native),
  };
}

// MIT — Customer API for the original SF88/SF101 workspace recovery commands.
import { mkdtemp, realpath, rm } from 'node:fs/promises';
import { dirname, join, sep } from 'node:path';
import { tmpdir } from 'node:os';
import { NativeRuntime } from './runtime.mjs';
import { absolute, object, need, BuyerError, safeCode } from './store.mjs';

const SCHEMA = 'stellar-forge.sf88.workspace-recovery.v1';
const STATUSES = {
  snapshot: 'BUYER_STATE_BACKUP_CREATED',
  verify: 'BUYER_STATE_BACKUP_VERIFIED',
  restore: 'BUYER_STATE_RESTORED',
};
const frozen = value => {
  if (value && typeof value === 'object' && !Object.isFrozen(value)) {
    for (const child of Object.values(value)) frozen(child);
    Object.freeze(value);
  }
  return value;
};
function canonical(value) {
  need(absolute(value) === value && value !== sep, 'WORKSPACE_RECOVERY_CANONICAL_PATH_REQUIRED');
  return value;
}
function selection({ directory, stateRoot, inboxes = [], include = [] }) {
  canonical(directory); canonical(stateRoot);
  need(Array.isArray(inboxes) && Array.isArray(include) && inboxes.length <= 64 && include.length <= 64,
    'WORKSPACE_RECOVERY_ROOT_LIST_INVALID');
  return ['--dir', directory, '--state-root', stateRoot,
    ...inboxes.flatMap(path => ['--inbox', canonical(path)]),
    ...include.flatMap(path => ['--include', canonical(path)])];
}
function passphraseName(value) {
  need(typeof value === 'string' && /^[A-Z][A-Z0-9_]{4,63}$/.test(value),
    'WORKSPACE_RECOVERY_PASSPHRASE_NAME_INVALID');
  return value;
}
function archiveOptions({ bundle, passphraseEnv = 'SF88_BACKUP_PASSPHRASE',
  python = '/usr/bin/python3', expectedRecordSha256 }) {
  const args = ['--bundle', canonical(bundle), '--pass-env', passphraseName(passphraseEnv),
    '--python', canonical(python)];
  if (expectedRecordSha256 !== undefined) {
    need(typeof expectedRecordSha256 === 'string' && /^[a-f0-9]{64}$/.test(expectedRecordSha256),
      'WORKSPACE_RECOVERY_EXPECTED_RECORD_INVALID');
    args.push('--expect', expectedRecordSha256);
  }
  return args;
}
function completion(operation, native) {
  if (!native || native.schema !== SCHEMA || typeof native.stateRoot !== 'string' ||
      typeof native.directory !== 'string') return false;
  if (operation === 'inspect') return native.restoreMode === 'ORIGINAL_CANONICAL_STATE_ROOT' &&
    Array.isArray(native.selected) && Array.isArray(native.inboxes);
  return native.status === STATUSES[operation] &&
    /^[a-f0-9]{64}$/.test(native.recordSha256 ?? '');
}

/** Original completion metadata and subprocess outcome remain separate facts. */
export class WorkspaceRecoveryResult {
  constructor(operation, run, { started = false, errorCode = null, cleanupErrorCode = null } = {}) {
    this.operation = operation;
    this.native = object(run?.output) && run.output.schema === SCHEMA ? frozen(run.output) : null;
    this.process = Object.freeze({
      exitCode: run?.exitCode ?? null,
      exitSignal: run?.exitSignal ?? null,
      errorCode: run?.errorCode ?? errorCode,
      started,
      cleanupErrorCode,
    });
    this.completionReported = completion(operation, this.native);
    this.ok = this.completionReported && this.process.exitCode === 0 &&
      !this.process.exitSignal && !this.process.errorCode && !cleanupErrorCode;
    Object.freeze(this);
  }
}

/** An interrupted restore can already be published; inspect result, never retry blindly. */
export class WorkspaceRecoveryError extends BuyerError {
  constructor(code, result) {
    super(code, { result });
    this.name = 'WorkspaceRecoveryError';
  }
}

/** Does not create a Buyer, initialize a ledger, or create any buyer state directory. */
export class WorkspaceRecovery {
  constructor(options) {
    this.runtime = options instanceof NativeRuntime ? options : new NativeRuntime(options);
    this.applicationDirectory = null;
  }

  static fromBuyer(buyer) {
    need(buyer?.runtime instanceof NativeRuntime, 'ORIGINAL_BUYER_RUNTIME_REQUIRED');
    const recovery = new WorkspaceRecovery(buyer.runtime);
    recovery.applicationDirectory = canonical(buyer.stateDirectory);
    return recovery;
  }

  _selection(options) {
    need(Array.isArray(options.include), 'WORKSPACE_RECOVERY_ROOT_LIST_INVALID');
    return selection({ ...options, include: [...new Set([...options.include,
      ...(this.applicationDirectory ? [this.applicationDirectory] : [])])] });
  }

  async _command(operation, args, parent, signal) {
    let directory, run, problem = null, cleanupErrorCode = null, started = false;
    try {
      // Capture logs remain outside the quiesced source. Archive operations use
      // OS temporary storage, so a read-only mounted bundle stays usable.
      const canonicalParent = await realpath(parent);
      need(operation === 'verify' || operation === 'restore' || canonicalParent === parent,
        'WORKSPACE_RECOVERY_OPERATION_PARENT_INVALID');
      directory = await mkdtemp(join(canonicalParent, '.sf88-sdk-recovery-'));
      run = await this.runtime.run(args, { directory, signal, started: () => { started = true; } });
    } catch (error) {
      problem = safeCode(error?.code, 'WORKSPACE_RECOVERY_NATIVE_COMMAND_FAILED');
    } finally {
      if (directory) {
        try { await rm(directory, { recursive: true, force: true }); }
        catch (error) { cleanupErrorCode = safeCode(error?.code, 'WORKSPACE_RECOVERY_LOG_CLEANUP_FAILED'); }
      }
    }
    const result = new WorkspaceRecoveryResult(operation, run,
      { started, errorCode: problem, cleanupErrorCode });
    if (!result.ok) throw new WorkspaceRecoveryError(problem ?? result.process.errorCode ??
      cleanupErrorCode ?? (result.process.exitCode !== 0 || result.process.exitSignal ?
        'WORKSPACE_RECOVERY_NATIVE_COMMAND_FAILED' : 'WORKSPACE_RECOVERY_NATIVE_RESULT_INVALID'), result);
    return result;
  }

  inspect({ directory, stateRoot, inboxes = [], include = [], signal } = {}) {
    const args = this._selection({ directory, stateRoot, inboxes, include });
    return this._command('inspect', ['--inspect-workspace-backup', ...args], dirname(stateRoot), signal);
  }

  snapshot({ directory, stateRoot, inboxes = [], include = [], output, quiesced,
    passphraseEnv = 'SF88_BACKUP_PASSPHRASE', signal } = {}) {
    need(quiesced === true, 'WORKSPACE_RECOVERY_QUIESCED_SOURCE_REQUIRED');
    const args = this._selection({ directory, stateRoot, inboxes, include });
    args.push('--out', canonical(output), '--quiesced', '--pass-env', passphraseName(passphraseEnv));
    return this._command('snapshot', ['--backup-workspace', ...args], dirname(stateRoot), signal);
  }

  verify({ bundle, passphraseEnv, python, expectedRecordSha256, signal } = {}) {
    const args = archiveOptions({ bundle, passphraseEnv, python, expectedRecordSha256 });
    return this._command('verify', ['--verify-workspace-backup', ...args], tmpdir(), signal);
  }

  restore({ bundle, passphraseEnv, python, expectedRecordSha256, signal } = {}) {
    const args = archiveOptions({ bundle, passphraseEnv, python, expectedRecordSha256 });
    // The authenticated native record chooses the original root. No target
    // override, original-state deletion, rewrite, retry, or purchase is performed.
    return this._command('restore', ['--restore-workspace', ...args], tmpdir(), signal);
  }
}

// MIT — The existing native application bridge owns workspace binding and keys.
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { absolute, object, need, jsonBytes, writeBytes } from './store.mjs';

const bridge = buyer => join(buyer.runtime.directory, 'python', 'bridge.mjs');

export async function readWorkspace(buyer, directory, { configuration, signal } = {}) {
  directory = absolute(directory);
  let temporary, configurationPath;
  try {
    if (configuration !== undefined) {
      if (typeof configuration === 'string') configurationPath = absolute(configuration);
      else {
        need(object(configuration), 'WORKSPACE_REQUEST_CONFIGURATION_REQUIRED');
        const raw = jsonBytes(configuration);
        need(raw.length <= 65536, 'CONFIG_SIZE_LIMIT');
        temporary = await mkdtemp(join(buyer.stateDirectory, '.workspace-import-'));
        configurationPath = join(temporary, 'request.json');
        await writeBytes(configurationPath, raw, { exclusive: true });
      }
    }
    const native = await buyer.runtime.checked(['workspace-read', '--dir', directory,
      ...(configurationPath === undefined ? [] : ['--config', configurationPath])], {
      stateDirectory: buyer.stateDirectory, entryFile: bridge(buyer), signal,
      mode: 'ORIGINAL_PYTHON_WORKSPACE',
    });
    need(native.directory === directory && object(native.configuration) &&
      native.keyCustody === 'ORIGINAL_NODE_WORKSPACE', 'ORIGINAL_WORKSPACE_RESULT_MISMATCH');
    return { directory, configuration: native.configuration };
  } finally {
    if (temporary) await rm(temporary, { recursive: true, force: true });
  }
}

export function workspaceCommand(buyer, { directory, configPath, ticketSha256 }, check = false) {
  return { entryFile: bridge(buyer), args: [check ? 'workspace-check' : 'execute-workspace',
    '--dir', absolute(directory), '--config', absolute(configPath),
    '--ticket-sha', ticketSha256 ?? 'none'] };
}

export async function checkWorkspace(buyer, context, { intentId, signal } = {}) {
  const command = workspaceCommand(buyer, context, true);
  const native = await buyer.runtime.checked(command.args, {
    stateDirectory: buyer.stateDirectory, entryFile: command.entryFile, signal,
    mode: 'ORIGINAL_PYTHON_WORKSPACE_READY',
  });
  need(native.intentId === intentId && native.keyCustody === 'ORIGINAL_NODE_WORKSPACE',
    'ORIGINAL_WORKSPACE_RESULT_MISMATCH');
  return native;
}

// MIT. Select the original SF30 public object description for the existing buyer.
import {createHash} from 'node:crypto';
import {constants} from 'node:fs';
import {open} from 'node:fs/promises';
import {isAbsolute} from 'node:path';
import {config, operation, need, InputError} from './config.mjs';

const HASH = /^[a-f0-9]{64}$/;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const count = value => Number.isSafeInteger(value) && value > 0;

/** Shared original row selection for saved files and receiving applications.
 * The descriptor supplies product facts; the original buyer reviews payment. */
export function selectObjectDescriptionBytes(raw, {objectId, chunkBytes} = {}) {
  need(raw instanceof Uint8Array && raw.byteLength <= 8 * 1024 * 1024,
    'OBJECT_DESCRIPTION_BYTE_LIMIT');
  need(typeof objectId === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(objectId),
    'OBJECT_EXPLICIT_SELECTION_REQUIRED');
  let description;
  try { description = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)); }
  catch { throw new InputError('OBJECT_DESCRIPTION_JSON_INVALID'); }
  need(object(description) && description.schema === 'stellar-forge.s3-description.v1' &&
    Array.isArray(description.objects), 'OBJECT_ORIGINAL_S3_DESCRIPTION_REQUIRED');
  const selected = description.objects.filter(value => object(value) && value.id === objectId);
  need(selected.length === 1, 'OBJECT_DESCRIPTION_SELECTION_NOT_UNIQUE');
  const item = selected[0];
  need(['chunks','whole'].includes(item.mode) && Number.isSafeInteger(item.bytes) &&
    (item.mode === 'whole' ? item.bytes >= 0 && item.bytes <= item.maxBytes : item.bytes > 0) &&
    count(item.maxBytes) && item.maxBytes <= 1048576 &&
    typeof item.snapshot === 'string' && HASH.test(item.snapshot),
    'OBJECT_DESCRIPTION_DELIVERY_CONTRACT_INVALID');
  need(typeof item.path === 'string' && item.path.startsWith('/') &&
    typeof item.contentType === 'string' && item.contentType.length > 0 &&
    item.contentType.length <= 256 && !/[\r\n]/.test(item.contentType) &&
    typeof item.filename === 'string' && item.filename.length <= 120 &&
    /^[A-Za-z0-9][A-Za-z0-9_. -]*$/.test(item.filename) && !/[. ]$/.test(item.filename),
    'OBJECT_DESCRIPTION_DELIVERY_INVALID');
  need(item.expectedSha256 === undefined ||
    typeof item.expectedSha256 === 'string' && HASH.test(item.expectedSha256),
    'OBJECT_DESCRIPTION_DIGEST_INVALID');
  // A whole product has one fixed response. Its positive writer capacity is
  // one byte for an empty file, while its expected response length remains 0.
  const requested = chunkBytes ?? (item.mode === 'whole' ? Math.max(1,item.bytes) : item.maxBytes);
  if (item.mode === 'whole') need(requested === Math.max(1,item.bytes), 'OBJECT_WHOLE_FILE_SIZE_FIXED');
  else need(count(requested) && requested <= item.maxBytes, 'OBJECT_DESCRIPTION_CHUNK_LIMIT');
  return {
    ...(item.mode === 'whole' ? {deliveryMode:'whole'} : {}),
    bytes:item.bytes, chunkBytes:requested, expectedSnapshot:item.snapshot,
    expectedSha256:item.expectedSha256 ?? null, expectedContentType:item.contentType,
    selection:{schema:'stellar-forge.sf88.object-selection.v1',
      descriptionSha256:createHash('sha256').update(raw).digest('hex'),
      objectId:item.id, filename:item.filename, path:item.path},
  };
}

/** Offline selection of one row from the merchant's ORIGINAL objects.json.
 * The original buyer still binds and reviews each actual request and quote. */
export async function selectObjectDescription({descriptionPath, objectId, configPath, chunkBytes} = {}) {
  need(typeof descriptionPath === 'string' && isAbsolute(descriptionPath) &&
    !descriptionPath.includes('\0'), 'OBJECT_DESCRIPTION_ABSOLUTE_PATH_REQUIRED');
  const handle = await open(descriptionPath, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  let raw;
  try {
    const info = await handle.stat();
    need(info.isFile() && info.size <= 8 * 1024 * 1024, 'OBJECT_DESCRIPTION_FILE_INVALID');
    raw = await handle.readFile();
  } finally { await handle.close(); }
  const selected = selectObjectDescriptionBytes(raw, {objectId, chunkBytes});
  const source = await config(configPath), op = operation(source.operation), url = new URL(op.url);
  need(op.method === 'GET' && !url.search && url.pathname === selected.selection.path,
    'OBJECT_DESCRIPTION_BUYER_ROUTE_MISMATCH');
  return selected;
}
